@@ -0,0 +1,195 @@
+import { expect, test } from 'bun:test';
+import { type EvictReason, LRU } from '../src/lru.ts';
+
+function recorder() {
+  const log: [string, number, EvictReason][] = [];
+  return { log, onEvict: (k: string, v: number, r: EvictReason) => log.push([k, v, r]) };
+}
+
+test('a get hit makes the entry most recently used', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(2, 1000, () => t);
+  const rec = recorder();
+  cache.onEvict = rec.onEvict;
+  cache.set('a', 1);
+  cache.set('b', 2);
+  cache.get('a');
+  cache.set('c', 3);
+  expect(rec.log).toEqual([['b', 2, 'capacity']]);
+  expect(cache.keys()).toEqual(['c', 'a']);
+});
+
+test('an expired get removes the entry and reports it once', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(2, 100, () => t);
+  const rec = recorder();
+  cache.onEvict = rec.onEvict;
+  cache.set('a', 1);
+  t = 100;
+  expect(cache.get('a')).toBeUndefined();
+  expect(rec.log).toEqual([['a', 1, 'expired']]);
+  expect(cache.get('a')).toBeUndefined();
+  expect(rec.log).toEqual([['a', 1, 'expired']]);
+});
+
+test('expiry boundary is exact', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.set('a', 1);
+  t = 99;
+  expect(cache.get('a')).toBe(1);
+  t = 100;
+  expect(cache.get('a')).toBeUndefined();
+});
+
+test('overwrite gets a fresh ttl and the newest place, without a callback', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(2, 100, () => t);
+  const rec = recorder();
+  cache.onEvict = rec.onEvict;
+  cache.set('a', 1);
+  cache.set('b', 2);
+  t = 90;
+  cache.set('a', 3);
+  t = 150;
+  expect(cache.get('a')).toBe(3);
+  expect(cache.keys()).toEqual(['a']);
+  expect(rec.log).toEqual([]);
+});
+
+test('expired entries are removed before live ones', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(2, 100, () => t);
+  const rec = recorder();
+  cache.onEvict = rec.onEvict;
+  cache.set('a', 1);
+  t = 50;
