+  // Naive model: an array ordered oldest first.
+  let model: { key: number; value: number; expiresAt: number }[] = [];
+  const modelLive = (e: { expiresAt: number }) => t < e.expiresAt;
+  const modelLog: [number, number, EvictReason][] = [];
+  const mRemove = (e: { key: number; value: number }, r: EvictReason) => {
+    model = model.filter((x) => x !== e);
